import com.androidhit.lumadrift.engine.*;
import java.nio.file.*;
import java.util.*;

/** Content acceptance uses an independent all-branch oracle, never just a stored solution. */
public final class LearningV114Test {
    static long checks,states,edges;
    static void check(boolean ok,String detail){checks++;if(!ok)throw new AssertionError(detail);}
    static void invalid(Runnable action){try{action.run();throw new AssertionError("Expected rejection");}catch(IllegalArgumentException expected){checks++;}}
    static int switches(Level level){int count=0;for(Tile tile:level.tiles)if(tile.switchMask!=0)count++;return count;}
    static void walk(Board board,AuditJourneyV114.Costs oracle,BitSet visited){int key=(int)((board.remainingMask()<<4)|board.gateMask());if(visited.get(key))return;visited.set(key);states++;long mask=board.remainingMask();int gates=board.gateMask();check(board.minimumActionsToFinish()==oracle.min(mask,gates),"Independent minimum at every intro state");check(board.hasSolution()&&!board.isDeadEnd(),"Every reached intro state remains logically solvable");
        for(int action:oracle.actions(mask,gates,0)){check(board.previewAction(action).legal,"Independent legal action agrees with preview");check(board.performAction(action).success,"Independent legal action is executable");edges++;walk(board,oracle,visited);check(board.undo()&&board.remainingMask()==mask&&board.gateMask()==gates,"Exit/open undo restores physical state");}
        for(Tile tile:board.level.tiles)check(board.canMove(tile.id)==(oracle.spatial(mask,tile)&&(gates&tile.direction.bit)!=0),"Every tile agrees with independent obstruction+gate model");
    }
    static void identicalGeometry(Level fresh,Level original){check(fresh.size==original.size&&fresh.initialGateMask==original.initialGateMask&&fresh.tiles.size()==original.tiles.size()&&fresh.barriers.size()==original.barriers.size(),"Reordered geometry bounds exact");for(Tile tile:fresh.tiles){Tile old=original.tile(tile.id);check(tile.row==old.row&&tile.col==old.col&&tile.direction==old.direction&&tile.switchMask==old.switchMask,"Reordered tile exact");}for(int i=0;i<fresh.barriers.size();i++){Barrier b=fresh.barriers.get(i),old=original.barriers.get(i);check(b.row==old.row&&b.col==old.col&&b.keyTileId==old.keyTileId,"Reordered seal association exact");}check(fresh.minimumActions==original.minimumActions,"Minimum of reordered geometry exact");}
    public static void main(String[]args)throws Exception{Path out=Paths.get(args.length>0?args[0]:"docs/validation/v1.14/audit-learning");Files.createDirectories(out);Set<String> unique=new HashSet<>();Set<Integer> sources=new HashSet<>();int previousScore=0,maxRise=0,hard=0,expert=0,peaks=0,recoveries=0,meaningful=0,maxPieceIncrease=0,maxActionIncrease=0,previousPieces=2,previousMin=2;long gateStates=0;StringBuilder csv=new StringBuilder("level,minimum,goal,maximum_all_legal,maximum_immediately_useful,maximum_exits_first,independent_gate_states\n");
        for(int n=1;n<=LearningCatalog.LEVEL_COUNT;n++){Level level=LearningCatalog.get(n);ProgressionInfo info=LearningCatalog.info(n);check(level.progressionVersion==5&&info.version==5,"N version5");check(unique.add(ProgressionAnalysis.canonical(level)),"N board unique under D4/translation/reorderedIDs: "+n);check(info.minimumActions==level.minimumActions&&info.mistakeAllowance==LearningCatalog.allowance(n),"Published preview data exact");check(level.tiles.size()<=20&&level.size<=7,"Finite solver bounds");for(Tile tile:level.tiles)check(Integer.bitCount(tile.switchMask)<=1,"No unintroduced dual-mask switches");
            if(n<=30){String expected=n<=4?"exits":n<=8?"blockers":n<=12?"key":n<=16?"gate":n<=20?"switch":n<=24?"switch_order":n<=27?"key_switch":"combination";check(LearningCatalog.lesson(n).equals(expected),"Explicit lesson phase");check(level.size==(n<=4?4:5),"Small intro grid");check(level.tiles.size()<=10,"Bounded intro density");check(switches(level)<=(n<=16?0:n<=20?1:n<=27?2:3),"Bounded intro switch count");check(info.keyCount<=(n>=9&&n<=12||n>=25?1:0),"No early key mixture");if(n<=12)check(level.initialGateMask==15&&info.requiredGateOpens==0,"No manual gate before own lesson");if(n>=13&&n<=16)check(info.requiredGateOpens==1&&switches(level)==0&&level.barriers.isEmpty(),"One isolated gate mechanic");if(n>=17&&n<=20)check(info.keyCount==0&&switches(level)==1,"One isolated switch mechanic");
                AuditJourneyV114.Costs oracle=new AuditJourneyV114.Costs(level);walk(new Board(level),oracle,new BitSet());}
            else{int source=LearningCatalog.sourceNumber(n);check(source>=31&&source<=1000&&sources.add(source),"970 distinct preserved source geometries");identicalGeometry(level,StrategyCatalog.get(source));int sizeCap=n<=60?5:n<=400?6:7,pieceCap=n<=60?13:n<=100?15:n<=160?17:n<=240?19:20,switchCap=n<=60?3:n<=100?4:n<=160?5:n<=240?6:9,keyCap=n<=160?1:2,sealCap=n<=400?2:3,minCap=n<=60?18:n<=100?19:n<=160?21:n<=240?26:n<=400?27:28,depthCap=n<=160?9:n<=240?13:12;
                check(level.size<=sizeCap&&level.tiles.size()<=pieceCap&&switches(level)<=switchCap&&info.keyCount<=keyCap&&level.barriers.size()<=sealCap&&level.minimumActions<=minCap&&info.dependencyDepth<=depthCap,"All mechanical phase caps hold N"+n);check(info.structuralScore-previousScore<=35,"No positive structural jump above35 after intro");}
            AuditJourneyV114.Costs oracle=new AuditJourneyV114.Costs(level);int minimum=oracle.min(level.allTilesMask,level.initialGateMask);check(minimum==level.minimumActions,"Independent exact initial minimum, all1000");gateStates+=(oracle.masks+1)*16;int a=oracle.maximum(level.allTilesMask,level.initialGateMask,0),u=oracle.maximum(level.allTilesMask,level.initialGateMask,1),g=oracle.maximum(level.allTilesMask,level.initialGateMask,2);check(a>=u&&u>=g&&g>=minimum,"Nested legal policy bounds");int budget=level.minimumActions+LearningCatalog.allowance(n);csv.append(n).append(',').append(minimum).append(',').append(budget).append(',').append(a).append(',').append(u).append(',').append(g).append(',').append((oracle.masks+1)*16).append('\n');
            Board board=new Board(level);for(int action:level.actionSolution)check(board.performAction(action).success,"Stored plan obeys actual N engine");check(board.isSolved()&&board.moves()==minimum,"Stored plan has independent exact length");Board restored=new Board(level);check(restored.restoreHistory(board.history())&&restored.isSolved(),"N typed history roundtrip");check(!restored.restoreHistory(new int[]{Integer.MAX_VALUE})&&restored.isSolved(),"Malformed N history rejected atomically");
            maxRise=Math.max(maxRise,info.structuralScore-previousScore);maxPieceIncrease=Math.max(maxPieceIncrease,level.tiles.size()-previousPieces);maxActionIncrease=Math.max(maxActionIncrease,minimum-previousMin);previousScore=info.structuralScore;previousPieces=level.tiles.size();previousMin=minimum;if(info.difficulty==ProgressionInfo.Difficulty.HARD)hard++;if(info.difficulty==ProgressionInfo.Difficulty.EXPERT)expert++;if(info.beat==ProgressionInfo.Beat.PEAK)peaks++;if(info.beat==ProgressionInfo.Beat.RECOVERY)recoveries++;if(info.decisionPoints>0)meaningful++;
        }
        check(sources.size()==970,"All970 sources present");invalid(()->LearningCatalog.get(0));invalid(()->LearningCatalog.get(1001));invalid(()->LearningCatalog.info(10,true));check(LearningCatalog.get(15).minimumActions==6&&LearningCatalog.get(15).tiles.size()==5&&switches(LearningCatalog.get(15))==0&&LearningCatalog.get(15).barriers.isEmpty(),"N15 isolates manual gate");
        Files.writeString(out.resolve("audit-learning-branches.csv"),csv);String report="{\n  \"passed\":true,\n  \"scope\":\"1000 N boards, exact independent finite branch bounds; exhaustive runtime first30 states;970 exact geometry equivalences to preserved V4; not human comprehension, win rate or enjoyment\",\n  \"checks\":"+checks+",\n  \"boards\":1000,\n  \"uniqueUnderD4TranslationAndIds\":1000,\n  \"preservedGeometrySources\":970,\n  \"independentGateStates\":"+gateStates+",\n  \"introRuntimeStates\":"+states+",\n  \"introRuntimeTransitions\":"+edges+",\n  \"meaningfulChoiceBoards\":"+meaningful+",\n  \"hardBoards\":"+hard+",\n  \"expertBoards\":"+expert+",\n  \"peaks\":"+peaks+",\n  \"recoveries\":"+recoveries+",\n  \"maximumPositiveScoreStep\":"+maxRise+",\n  \"maximumPieceIncrease\":"+maxPieceIncrease+",\n  \"maximumMinimumActionIncrease\":"+maxActionIncrease+"\n}\n";Files.writeString(out.resolve("audit-learning-contracts.json"),report);System.out.println(report);
    }
}
